<?php /** @var array $requests */ /** @var object $pager */ /** @var string $search */ /** @var string $status */ ?>
<div class="page__section"><div class="card"><div class="card__header"><span class="card__title">Review Pengajuan BHP</span></div><div class="card__body"><form method="get" action="<?= base_url('bhp-approval') ?>" style="display:flex;flex-wrap:nowrap;align-items:end;gap:.5rem;overflow-x:auto;padding-bottom:.25rem"><input class="input" style="min-width:18rem" name="q" value="<?= esc($search) ?>" placeholder="Cari kode atau laboratorium"><select class="input" style="min-width:12rem" name="status"><option value="">Semua antrian</option><option value="PENDING_REVIEW" <?= $status === 'PENDING_REVIEW' ? 'selected' : '' ?>>Menunggu Review</option><option value="EVIDEN_SUBMITTED" <?= $status === 'EVIDEN_SUBMITTED' ? 'selected' : '' ?>>Eviden Dikirim</option></select><button class="button button--outline" type="submit">Filter</button></form><div class="table-responsive" style="margin-top:1rem"><table class="table"><thead><tr><th>Kode</th><th>Laboratorium</th><th>Pemohon</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if (empty($requests)): ?><tr><td colspan="5"><?= view('partials/empty_table_state', ['message' => 'Tidak ada pengajuan yang menunggu tindakan.']) ?></td></tr><?php endif; ?><?php foreach ($requests as $row): ?><tr><td><?= esc($row['kode_pengajuan']) ?></td><td><?= esc($row['laboratory_name']) ?></td><td><?= esc($row['laboran_id']) ?></td><td><?= esc($row['status']) ?></td><td><a class="button button--info button--sm" href="<?= base_url('bhp/detail/' . $row['uuid']) ?>">Detail</a><?php if ($row['status'] === 'PENDING_REVIEW'): ?><form method="post" action="<?= base_url('bhp-approval/' . $row['uuid'] . '/approve') ?>" style="display:inline"><?= csrf_field() ?><button class="button button--success button--sm">Setujui</button></form><form method="post" action="<?= base_url('bhp-approval/' . $row['uuid'] . '/revise') ?>" style="display:inline"><input name="note" placeholder="Catatan revisi" required><?= csrf_field() ?><button class="button button--warning button--sm">Revisi</button></form><form method="post" action="<?= base_url('bhp-approval/' . $row['uuid'] . '/reject') ?>" style="display:inline"><input name="note" placeholder="Alasan penolakan" required><?= csrf_field() ?><button class="button button--danger button--sm">Tolak</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?= $pager->links() ?></div></div></div>
